#!/bin/sh
# THE VENDORED zlib AND brotli, made from their release tarballs and
# nothing else. Re-run to upgrade: it replaces vendor/zlib/,
# vendor/brotli/ and every unit wrapper, so what is checked in is
# always this script's output.
#
#   sh packages/std-compress/vendor/import.sh zlib-1.3.1.tar.gz brotli-1.1.0.tar.gz
#
# ONE OBJECT PER UPSTREAM UNIT. Each wrapper includes one upstream .c
# and nothing else, so every unit compiles as upstream compiles it; the
# wrapper's name gives the object a stem unique tree-wide. Only the
# units the package's C reaches are vendored: zlib's deflate and inflate
# and what they call (no gz* file layer), brotli's common, dec and enc.
set -eu
zlib_tar=$1
brotli_tar=$2
zlib_sha=9a93b2b7dfdac77ceba5a558a580e74667dd6fede4585b91eefb60f03b72df23
brotli_sha=e720a6ca29428b803f4ad165371771f5398faba397edf6778837a18599ea13ff
here=$(cd "$(dirname "$0")" && pwd)

check() {
    got=$(shasum -a 256 "$1" | cut -d' ' -f1)
    if [ "$got" != "$2" ]; then
        echo "import: $1 is not the release this script pins (sha256 $got)" >&2
        exit 1
    fi
}
check "$zlib_tar" "$zlib_sha"
check "$brotli_tar" "$brotli_sha"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
tar -xzf "$zlib_tar" -C "$work"
tar -xzf "$brotli_tar" -C "$work"

rm -rf "$here/zlib" "$here/brotli" "$here"/zlib_*.c "$here"/brotli_*.c
mkdir -p "$here/zlib" "$here/brotli"

zlib_units="adler32 crc32 deflate inffast inflate inftrees trees zutil"
for u in $zlib_units; do cp "$work/zlib-1.3.1/$u.c" "$here/zlib/"; done
cp "$work"/zlib-1.3.1/*.h "$work/zlib-1.3.1/LICENSE" "$here/zlib/"
for u in $zlib_units; do
    printf '/* generated by import.sh: one upstream unit */\n#include "zlib/%s.c"\n' "$u" > "$here/zlib_$u.c"
done

for d in common dec enc include; do cp -R "$work/brotli-1.1.0/c/$d" "$here/brotli/"; done
cp "$work/brotli-1.1.0/LICENSE" "$here/brotli/"
for f in "$here"/brotli/common/*.c "$here"/brotli/dec/*.c "$here"/brotli/enc/*.c; do
    d=$(basename "$(dirname "$f")")
    u=$(basename "$f" .c)
    printf '/* generated by import.sh: one upstream unit */\n#include "brotli/%s/%s.c"\n' "$d" "$u" > "$here/brotli_${d}_$u.c"
done
